// =================================================================================================
// FIREMAKING — burnLogs
// =================================================================================================
// PACKET A (inventory, preferred): useItemOnItem(TINDERBOX, tbSlot, logObj, logSlot).
//   -> [opheldu,tinderbox] -> switch_category(category_22) -> @light_logs_inv(last_useslot).
//   The script inv_dropslot's the log onto your tile FIRST, then rolls; on failure it re-arms with
//   p_opobj(4), so ONE send burns the log to completion or to a refusal.
// PACKET B (a log already on the ground): opObj(x, z, logObj, 4).
//   -> [opobj4,_category_22] -> @light_logs_ground. Same loop. OPOBJ self-routes naively.
// ⛔ ON SUCCESS THE SERVER MOVES YOU. ~push_player p_teleports one tile — west, then east, then south,
//   then north, first walkable wins — so the fire is on your OLD tile. Re-read your tile after every
//   "The fire catches..." or the next drop lands on the fire and refuses with "You can't light a fire
//   here." A fire burns 100..200 ticks, then leaves ashes.
// ⛔ BANK ZONES REFUSE. area_allow_loc_add() rejects any coord inside a bank_zones pair — burning next
//   to a bank booth is impossible by design, not a pathing bug.
export const BURN_GROUND_OP = 4;
export const TINDERBOX = 590;
export const ASHES = 592;

export interface LogEntry {
    readonly name: string;
    readonly obj: number;
    /** firemaking level; 0 means the obj carries no levelrequire param (param default) */
    readonly level: number;
    /** firemaking xp in tenths; 0 means the obj carries no productexp param — IT BURNS FOR NOTHING */
    readonly xp: number;
    readonly members: boolean;
    /** true when the obj has its own [opheldu,<obj>] trigger that outranks [opheldu,tinderbox] */
    readonly hasOwnTrigger: boolean;
}

