// =================================================================================================
// STRINGING — stringAmulet
// =================================================================================================
// PACKET: useItemOnItem(BALL_OF_WOOL, woolSlot, unstrungObj, unstrungSlot)
//   -> [opheldu,ball_of_wool] -> @string_amulet(last_useslot). ONE amulet per send, synchronous, no
//      interface and no queue.
// ⛔ THERE IS NO LEVEL CHECK AND NO XP TABLE: string_amulet hard-codes stat_advance(crafting, 40) for
//   every amulet, and never reads levelrequired. The 'level' below is the level to CRAFT the unstrung
//   piece, kept for planning; it is NOT enforced on stringing.
export const BALL_OF_WOOL = 1759;
