// =================================================================================================
// ENCHANT — enchantItem
// =================================================================================================
// PACKET: opHeldT(targetObj, targetSlot, ENCHANT_SPELLS[i].com) — the same primitive leanbot already
//   uses for high-alch (magic:highlvl_alchemy = 1178). One cast per send; p_delay(1) after.
// ⛔ THE SPELL COMPONENT'S GREY-OUT IS CLIENT-ONLY. magic.if gates each icon with script1..3 (rune
//   count, staff worn, magic level) but OpHeldTHandler only checks actiontarget=heldobj and that the
//   magic tab is open. So a headless bot may fire unconditionally and READ THE REFUSAL — it never has
//   to model the icon state. That is a real headless advantage over the text-scanning SDK path.
// ⛔ THE ITEM IS REPLACED IN PLACE. inv_setslot, not del+add: the enchanted item keeps its slot, so a
//   count-based success detector sees NO inventory-length change. Watch the slot's obj id, or the
//   magic xp, or the "You successfully enchant the ..." message.
// FAILURE MODES, in the order the server checks them:
//   members world -> MESSAGES.enchant.membersSpell
//   magic level   -> MESSAGES.enchant.lowLevel
//   runes         -> MESSAGES.enchant.noRunesPrefix + <rune name> + noRunesSuffix
//   wrong target  -> unstrungMessage (if the target is the matching UNSTRUNG amulet), else
//                    wrongTargetMessage
// A staff in the right hand substitutes for its element's rune (~staff_runes), so the rune list below
// is the WORST case.
export interface EnchantConversion {
    readonly from: string;
    readonly fromObj: number;
    readonly to: string;
    readonly toObj: number;
}

export interface EnchantSpell {
    /** 1..5 */
    readonly tier: number;
    readonly constant: string;
    /** magic-tab component; pass as opHeldT's spellCom */
    readonly com: number;
    readonly comName: string;
    readonly level: number;
    /** magic xp in tenths */
    readonly xp: number;
    readonly members: boolean;
    /** worst case — an elemental staff can replace its own rune */
    readonly runes: readonly { readonly rune: string; readonly obj: number; readonly count: number }[];
    readonly conversions: readonly EnchantConversion[];
    /** shown when the target is not enchantable by this tier at all */
    readonly wrongTargetMessage: string;
    /** shown when the target is the matching UNSTRUNG amulet (string it first) */
    readonly unstrungMessage: string | null;
    readonly unstrungObj: number | null;
}

